import * as T from 'three';
import {OrbitControls} from '/vendor/OrbitControls.js';
import {generateScene} from './scene-layout.js';
import {initTheme,getTheme,setTheme,usePreset,applyToThree} from './theme-engine.js';
const $=id=>document.getElementById(id),host=$('scene-viewport'),status=$('scene-status');
const scene=new T.Scene();scene.background=new T.Color('#e8edde');
const renderer=new T.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;host.append(renderer.domElement);
const camera=new T.PerspectiveCamera(35,1,.1,500),orbit=new OrbitControls(camera,renderer.domElement);orbit.maxPolarAngle=Math.PI*.47;orbit.minDistance=8;orbit.maxDistance=120;
scene.add(new T.HemisphereLight('#fff5df','#82906f',2.2));const sun=new T.DirectionalLight('#fff1da',2.8);sun.position.set(-15,27,15);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-25,right:25,top:25,bottom:-25,near:1,far:85});sun.shadow.normalBias=.025;scene.add(sun);
let world,layout,records=[],serial=0,busy=false,settings={seed:1,radius:3};const templates=new Map();
function render(){renderer.render(scene,camera)}orbit.addEventListener('change',()=>{render();window.RanchView?.changed()});
function fit(top=false){if(!world)return;const box=new T.Box3().setFromObject(world),center=box.getCenter(new T.Vector3()),r=box.getSize(new T.Vector3()).length()/2,angle=Math.min(camera.fov*Math.PI/360,Math.atan(Math.tan(camera.fov*Math.PI/360)*camera.aspect));camera.position.copy(center).add(new T.Vector3(top?.01:1,top?1:1.05,top?.01:1.25).normalize().multiplyScalar(r/Math.sin(angle)*1.1));orbit.target.copy(center);orbit.update();render()}
new ResizeObserver(()=>{renderer.setSize(host.clientWidth,host.clientHeight,false);camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();fit()}).observe(host);
function surface(color,role){return {color:new T.Color(color).convertLinearToSRGB().toArray(),role}}
function primitive(geometry,color,role){const mesh=new T.Mesh(geometry,new T.MeshStandardMaterial({color,roughness:.9}));mesh.userData.ownedGeometry=true;mesh.userData.themeSurface=surface(color,role);mesh.receiveShadow=true;return mesh}
async function template(id){if(!templates.has(id))templates.set(id,(async()=>{const record=records.find(r=>r.id===id);if(!record)throw Error('Unknown model: '+id);const r=await fetch(record.json);if(!r.ok)throw Error('Could not load '+id);const parts=await r.json(),g=new T.Group();for(const part of parts){const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(part.positions,3));if(part.normals?.length===part.positions.length)geo.setAttribute('normal',new T.Float32BufferAttribute(part.normals,3));else geo.computeVertexNormals();const mesh=new T.Mesh(geo,new T.MeshStandardMaterial({color:new T.Color().setRGB(...part.color,T.SRGBColorSpace),roughness:.9}));mesh.userData.themeSurface=part;mesh.castShadow=mesh.receiveShadow=true;g.add(mesh)}return g})().catch(e=>{templates.delete(id);throw e}));return templates.get(id)}
function dispose(group){group.traverse(m=>{if(m.userData.ownedGeometry||m.userData.ranchBlossoms)m.geometry?.dispose();m.material?.dispose()})}
function setBusy(value){busy=value;for(const id of ['scene-generate','scene-rebuild','scene-load','scene-save','scene-export'])$(id).disabled=value;host.setAttribute('aria-busy',String(value))}
async function build(input){const ticket=++serial;setBusy(true);status.textContent='Composing fields, paths and places…';let next;try{const plan=generateScene(input);await Promise.all([...new Set(plan.placements.map(p=>p.assetId))].map(template));if(ticket!==serial)return;next=new T.Group();for(const tile of plan.tiles){const base=primitive(new T.CylinderGeometry(1.98,1.98,.4,6),'#94795b','soil');base.position.set(tile.x,-.25,tile.z);next.add(base);const wet=['water','pond'].includes(tile.kind);const top=primitive(new T.CylinderGeometry(1.98,1.98,.1,6),wet?'#8dbac0':tile.kind==='path'||tile.kind==='courtyard'?'#d8c7a3':'#a4b781',wet?'water':tile.kind==='path'||tile.kind==='courtyard'?'unmapped':'foliage');top.position.set(tile.x,0,tile.z);next.add(top)}
for(const path of plan.paths||[]){const a=new T.Vector3(path.from.x,.067,path.from.z),b=new T.Vector3(path.to.x,.067,path.to.z),delta=b.clone().sub(a);const road=primitive(new T.BoxGeometry(.4,.025,delta.length()),'#dbc7a2','unmapped');road.position.copy(a).add(b).multiplyScalar(.5);road.rotation.y=Math.atan2(delta.x,delta.z);next.add(road)}
for(const p of plan.placements){const model=(await template(p.assetId)).clone(true);model.traverse(m=>{if(m.material)m.material=m.material.clone()});const box=new T.Box3().setFromObject(model),size=box.getSize(new T.Vector3()),center=box.getCenter(new T.Vector3()),scale=(p.scale||2)/Math.max(size.x,size.z);model.scale.setScalar(scale);for(const child of model.children){child.position.x-=center.x;child.position.z-=center.z;child.position.y-=box.min.y}model.position.set(p.x,.055,p.z);model.rotation.y=p.rotation||0;next.add(model)}applyToThree(next,T);if(world){scene.remove(world);dispose(world)}world=next;scene.add(world);layout=plan;settings={seed:plan.seed,radius:Number(input.radius)};$('scene-seed').value=settings.seed;$('scene-size').value=settings.radius;$('scene-caption').textContent=plan.tiles.length+' hexes · '+plan.placements.length+' ranch pieces · Drag to explore';$('scene-summary').textContent='Seed '+settings.seed+'. '+plan.placements.length+' models arranged across connected hex terrain.';status.textContent='Ranch ready. Generate again for a new arrangement.';fit();window.RanchView?.changed()}catch(e){if(next)dispose(next);status.textContent=e.message;console.error(e)}finally{if(ticket===serial)setBusy(false)}}
function fresh(){return crypto.getRandomValues(new Uint32Array(1))[0]||1}
function recipe(){return {version:1,kind:'ranch-hex-scene',settings,theme:getTheme(),layout}}
$('scene-generate').onclick=()=>{build({seed:fresh(),radius:Number($('scene-size').value)});if(innerWidth<800)window.RanchDrawers?.close()};
$('scene-rebuild').onclick=()=>{const seed=Number($('scene-seed').value);if(!Number.isInteger(seed)||seed<1||seed>4294967295){status.textContent='Enter a whole-number seed from 1 to 4294967295.';return}build({seed,radius:Number($('scene-size').value)});if(innerWidth<800)window.RanchDrawers?.close()};
$('scene-fit').onclick=()=>fit();$('scene-top').onclick=()=>fit(true);
$('scene-save').onclick=()=>{try{localStorage.setItem('ranch-scene-v1',JSON.stringify(recipe()));status.textContent='Scene and theme saved on this device.'}catch{status.textContent='Device storage is unavailable. Download the recipe instead.'}};
$('scene-load').onclick=()=>{try{const saved=JSON.parse(localStorage.getItem('ranch-scene-v1'));if(saved?.kind!=='ranch-hex-scene'||![2,3,4].includes(saved.settings?.radius)||!Number.isInteger(saved.settings?.seed))throw Error('No valid saved scene on this device.');setTheme(saved.theme);build(saved.settings)}catch(e){status.textContent=e.message}};
$('scene-export').onclick=()=>{if(!layout)return;const url=URL.createObjectURL(new Blob([JSON.stringify(recipe(),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='ranch-scene-'+settings.seed+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Scene recipe downloaded.'};
window.addEventListener('ranch-theme-change',()=>{if(world)applyToThree(world,T);$('scene-theme').value=getTheme().preset;render();window.RanchView?.changed()});
async function start(){const contract=await initTheme();$('scene-theme').append(...contract.presets.map(p=>new Option(p.label,p.id)),new Option('Your theme','custom'));$('scene-theme').value=getTheme().preset;$('scene-theme').onchange=e=>{if(e.target.value!=='custom')usePreset(e.target.value)};const r=await fetch('/simulation-assets/catalog.json');if(!r.ok)throw Error('Asset library unavailable');records=await r.json();window.RanchView?.register('sceneGenerator',()=>({settings,theme:getTheme(),tiles:layout?.tiles.length,placements:layout?.placements.length,busy,camera:camera.position.toArray()}),render);await build({seed:fresh(),radius:3})}start().catch(e=>{status.textContent=e.message;console.error(e)});
